// Deterministic status flow. Level-1 verification: exactly one record match PLUS a
// confirmed non-sensitive factor from the current message (first name / business name / ZIP).
// Level-2 provider unconfigured => escalate (ASSUMPTIONS A-14). Default = less disclosure.
const inp = $('When Executed by Another Workflow').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.key);
const cfg = {}; rows.forEach(r => { cfg[r.key] = r.value; });
const resolution = JSON.parse(inp.resolution || '{}');
const statusMap = JSON.parse($env.STATUS_MAP_JSON || '{"stages":[]}');
const policy = JSON.parse($env.DISCLOSURE_POLICY_JSON || '{}');
const templates = JSON.parse($env.FALLBACK_MESSAGES_JSON || '{}').templates || {};
const text = (inp.inbound_content || '').toLowerCase();
let route, content = null, templateId = null;
if (cfg.status_lookup_enabled !== 'true' || cfg.global_ai_enabled !== 'true') { route = 'disabled'; }
else if (resolution.outcome === 'multiple_match') { route = 'escalate'; content = templates.ambiguous_record; templateId = 'ambiguous_record'; }
else if (resolution.outcome !== 'single_match') { route = 'unverified'; content = templates.identity_confirmation_failed; templateId = 'identity_confirmation_failed'; }
else {
  const s = resolution.sanitized || {};
  // Confirmation factor check against the CURRENT message (deterministic containment of a known factor value).
  const norm = (v) => String(v || '').trim().toLowerCase().replace(/[^a-z0-9 ]/g, '');
  const factors = (policy.levels && policy.levels['1'] && policy.levels['1'].confirmation_factors) || ['first_name', 'business_name', 'zip_code'];
  const confirmed = factors.some(f => { const v = norm(s[f]); return v && v.length >= 3 && norm(text).includes(v); });
  if (!confirmed) { route = 'need_confirmation'; content = templates.identity_confirmation_request; templateId = 'identity_confirmation_request'; }
  else {
    // Level 1 achieved. Map internal value -> customer-safe stage.
    const appSel = resolution.application_selection || { outcome: 'none' };
    let obj, field, value;
    if (appSel.outcome === 'selected' && appSel.application && appSel.application.stage) { obj = 'Opportunity'; field = 'StageName'; value = appSel.application.stage; }
    else if (appSel.outcome === 'ambiguous') { route = 'escalate'; content = templates.ambiguous_record; templateId = 'ambiguous_record'; }
    else { obj = 'Lead'; field = 'Status'; value = s.lead_status; }
    if (!route) {
      const hit = (statusMap.stages || []).find(st => st.active && st.internal_object === obj && st.internal_field === field && (st.internal_values || []).includes(String(value)));
      if (!hit) { route = 'escalate'; content = templates.verification_escalation; templateId = 'verification_escalation'; }
      else if (hit.verification_level >= 2) {
        // Level 2 required — provider pluggable, unconfigured => human (A-14).
        route = 'escalate'; content = templates.verification_escalation; templateId = 'verification_escalation';
      } else if (hit.human_escalation_required) { route = 'escalate_with_status'; content = (templates.status_response || '{status_wording} {next_step}').replace('{status_wording}', hit.customer_wording || '').replace('{next_step}', 'A specialist will follow up with the details.'); templateId = 'status_response'; }
      else { route = 'answer'; content = (templates.status_response || '{status_wording} {next_step}').replace('{status_wording}', hit.customer_wording || '').replace('{next_step}', hit.next_step || ''); templateId = 'status_response'; }
    }
  }
}
const escalate = ['escalate', 'escalate_with_status'].includes(route);
console.log(JSON.stringify({ level: 'info', workflow: 'SB-05', workflow_version: '1.0.0', correlation_id: inp.correlation_id, action: 'status_lookup', route, record_ref: resolution.sanitized ? resolution.sanitized.record_ref : null, ts: new Date().toISOString() }));
return [{ json: { correlation_id: inp.correlation_id, customer_number: inp.customer_number, customer_ref: inp.customer_ref, record_ref: resolution.sanitized ? resolution.sanitized.record_ref : null, route, content: content ? content.trim() : null, template_id: templateId, escalate, resolution: inp.resolution } }];
